package com.fixmer.mared.technology.server.setup;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;
import java.nio.file.*;import java.util.*;
/** Primary workflow: folder and one start/restart button. Logs and exceptional decisions are advanced. */
public final class InPlaceServerScreen104 extends MaredScreen {
 private final Screen previous;private EditBox folder;private Button primary,browse,advanced;private int left,w,top,scroll,maxScroll;private boolean remoteLayout;private String submitted="";private long sent;private String initialGeneration="";private Object serverConnection;private boolean knownRemote104;
 public InPlaceServerScreen104(Screen previous){super(tr("title"));this.previous=previous;}
 private static Component tr(String key,Object...args){return Component.translatable("mared.server104."+key,args);}
 private boolean remote(){Object connection=minecraft==null?null:minecraft.getConnection();if(connection!=serverConnection){serverConnection=connection;knownRemote104=false;}if(connection!=null&&DedicatedPanelService75.hasRemote()&&DedicatedPanelService75.remote().getOrDefault("inplace104","false").equals("true"))knownRemote104=true;return connection!=null&&knownRemote104;}
 private Map<String,String> state(){return remote()?DedicatedPanelService75.remote():InPlaceServerService104.state();}
 private String phase(){String p=state().getOrDefault("phase","STOPPED");return p.equals("ACTIVE_BASELINE")||p.equals("ACTIVE_UPDATED")?"RUNNING":p;}
 @Override protected void init(){remoteLayout=remote();w=Math.max(1,Math.min(560,width-24));left=(width-w)/2;int y=42;folder=null;browse=null;
  if(!remoteLayout){folder=addRenderableWidget(new EditBox(font,left,y,w-38,20,tr("folder")));folder.setMaxLength(4096);folder.setValue(InPlaceServerService104.folder());folder.setHint(tr("folder"));browse=addRenderableWidget(Button.builder(Component.literal("…"),b->{save();Path initial;try{initial=folder.getValue().isBlank()?minecraft.gameDirectory.toPath():Path.of(folder.getValue());}catch(Exception e){initial=minecraft.gameDirectory.toPath();}minecraft.setScreen(new LocalPickerScreen68(this,true,initial,p->{folder.setValue(p.toString());save();}));}).bounds(left+w-32,y,32,20).build());y+=30;}
  primary=addRenderableWidget(Button.builder(tr("start"),b->start()).bounds(left,y,w,24).build());top=y+34;
  advanced=addRenderableWidget(Button.builder(tr("advanced"),b->{save();minecraft.setScreen(new InPlaceAdvanced104(this,folder==null?InPlaceServerService104.folder():folder.getValue().trim(),remote()));}).bounds(left,height-50,w,20).build());addRenderableWidget(Button.builder(tr("back"),b->onClose()).bounds(left,height-26,w,20).build());tick();
 }
 private void save(){if(folder!=null)InPlaceServerService104.folder(folder.getValue().trim());}
 private void start(){if(InPlaceServerService104.busy())return;save();submitted=phase().equals("RUNNING")?"RESTART":"START";sent=System.nanoTime();initialGeneration=state().getOrDefault("generation","");if(remote())DedicatedPanelService75.request("RESTART","r1");else InPlaceServerService104.action(folder.getValue().trim(),submitted.equals("RESTART")?"restart":"start");}
 @Override public void tick(){if(primary==null)return;if(remoteLayout!=remote()){save();rebuildWidgets();return;}if(DedicatedPanelService75.hasRemote())DedicatedPanelService75.poll(false,"");if(!remote()&&folder!=null)InPlaceServerService104.poll(folder.getValue().trim());String phase=phase();if(sent!=0&&(!initialGeneration.equals(state().getOrDefault("generation",""))||System.nanoTime()-sent>10_000_000_000L))sent=0;
  boolean busy=InPlaceServerService104.busy()||sent!=0||Set.of("STARTING","STOPPING","RESTARTING","WAITING_FOR_STOP","RECOVERY_REQUIRED").contains(phase);primary.setMessage(tr(phase.equals("RUNNING")?"restart":"start"));primary.active=!busy&&(remote()?DedicatedPanelService75.canRemote88("RESTART"):folder!=null&&!folder.getValue().isBlank());advanced.active=!InPlaceServerService104.busy();if(folder!=null)folder.setEditable(!busy);if(browse!=null)browse.active=!busy;
 }
 @Override public void onClose(){save();minecraft.setScreen(previous);}@Override public boolean isPauseScreen(){return false;}
 @Override public boolean mouseScrolled(double x,double y,double dx,double dy){scroll=Math.max(0,Math.min(maxScroll,scroll+(int)(-dy*22)));return true;}
 private List<Component> lines(){var result=new ArrayList<Component>();String phase=phase();if(InPlaceServerService104.busy())result.add(tr("working"));else if(sent!=0)result.add(tr("queued"));else result.add(tr("phase."+(Set.of("RUNNING","STARTING","STOPPING","RESTARTING","STOPPED","FAILED","WAITING_FOR_STOP","RECOVERY_REQUIRED","BOOTSTRAP_FAILED_RESTORED","OWNER_UNAVAILABLE").contains(phase)?phase:"STOPPED")));
  String error=remote()?state().getOrDefault("failureCode",""):InPlaceServerService104.result();if(error.isBlank()||error.equals("DONE"))error=state().getOrDefault("error","");if(!error.isBlank()&&!error.equals("DONE")){result.add(tr("error."+hint(error)));result.add(tr("log_hint"));}
  result.add(tr(remote()?"remote_hint":"folder_hint"));return result;
 }
 private static String hint(String code){return switch(code){case "SERVER104_ACCEPT_EULA"->"eula";case "SERVER104_BUILD_JAR_REQUIRED","SERVER104_CLIENT_BUILD","SERVER104_BOOTSTRAP_VERSION"->"build";case "SERVER104_LEGACY_WORLD_REVIEW"->"legacy";case "SERVER104_JAVA21"->"java";case "SERVER104_PORT_BUSY"->"port";case "SERVER104_DESKTOP_LAUNCH_UNAVAILABLE","SERVER104_INDEPENDENT_PARENT_REQUIRED"->"independent";default->"generic";};}
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xF0151820);g.drawCenteredString(font,title,width/2,12,0xFFFFFFFF);var rows=new ArrayList<net.minecraft.util.FormattedCharSequence>();for(Component c:lines())rows.addAll(font.split(c,Math.max(1,w-8)));int bottom=Math.max(top,height-58),step=font.lineHeight+3;maxScroll=Math.max(0,rows.size()*step-(bottom-top));scroll=Math.min(scroll,maxScroll);if(bottom>top){g.enableScissor(left,top,left+w,bottom);int y=top-scroll;for(var row:rows){if(y+step>=top&&y<bottom)g.drawString(font,row,left,y,0xFFCCD0DC,false);y+=step;}g.disableScissor();}super.render(g,mx,my,dt);}
}
